content.content:
480	      }
481	    case (s, t:VarType) => exc(t, s)
482	    // TODO: Check what happens when stem s = stem t
483	    case (s: TraitType, t: TraitType) =>
484	      def checkEC(s: TraitType, t: TraitType): CFormula = {
485	        def cEC(s: TraitType, t: TraitType) = pOr(excludesClause(s).map(e => withClauseParams(e).pSub(t, e)))
486	        pOr(cEC(s, t), cEC(t, s))
487	      }
488	      def checkCC(s: TraitType, t: TraitType): CFormula = {
489	        def cCC(s: TraitType, t: TraitType): CFormula = {
490	          val scc = comprisesClause(s)
491	          pAnd(pFromBoolean(!scc.isEmpty), pAnd(scc.map(pExc(t,_))))
492	        }
493	        pOr(cCC(s, t), cCC(t, s))
494	      }
495	      def checkO(s: TraitType, t: TraitType): CFormula = {
496	        def cO(s: TraitType, t: TraitType): CFormula = typeCons(s.getName) match {
497	          case _:ObjectTraitIndex => pSub(s, t)(!negate, history)
498	          case _ => pFalse()
499	        }
500	        pOr(cO(s,t), cO(t,s))
501	      }
502	      def checkP(s: TraitType, t: TraitType): CFormula = {
503	        val sas = ancestors(s) ++ Set(s)
504	        val tas = ancestors(t) ++ Set(t)
505	        def cP(s: BaseType, t: BaseType): CFormula = (s, t) match {
506	          case (s@STraitType(_, n1, a1, _), t@STraitType(_, n2, a2, _)) if (n1 == n2) =>
507	            //Todo: Handle bool args
508	            pOr((a1, a2).zipped.map{
509	              case (STypeArg(_, _, t1), STypeArg(_, _, t2)) => pEqv(t1, t2)(!negate, history)
510	              case (SIntArg(_, _, i1: IntBase), SIntArg(_, _, i2: IntBase)) => pEqv(i1, i2)(!negate)
511	              case _ => pFalse()
512	            })
513	          case _ => pFalse()
514	        }
515	        pOr(for(sa <- sas; ta <- tas) yield cP(sa, ta))
516	      }
517	      pOr(List(checkEC(s,t), checkCC(s,t), checkO(s,t), checkP(s,t)))
518	    // ToDo: Handle keywords. Note that this will mean you can have a tuple of length 1 without varargs.
519	    case (s@STupleType(_, e1, Some(v1), _), t@STupleType(_, e2, mv2, _)) =>
520	        pExc(disjunctFromTuple(s, max(e1.size, e2.size)), t)
521	    case (s@STupleType(_, e1, None, _), t@STupleType(_, e2, Some(v2), _)) => pExc(t, s)
522	    case (STupleType(_, e1, None, _), STupleType(_, e2, None, _)) if (e1.size == e2.size) =>
523	      pOr((e1, e2).zipped.map((a, b) => pExc(a, b)))
524	    case (STupleType(_, e1, None, _), STupleType(_, e2, None, _)) =>
525	      pTrue()
526	    case (s: TupleType, t) => pExc(disjunctFromTuple(s, 1), t)
527	    case (s, t: TupleType) => pExc(t, s)
528	    case (s: ArrowType, t: ArrowType) => pFalse()
529	    case (s: ArrowType, t) => pTrue()
530	    case (s, t: ArrowType) => pExc(t, s)
531	  }
