577	  protected def pNorm(x: Type)(implicit history: Set[hType]): Type = {
578	    object normalizer extends Walker {
579	      override def walk(y: Any): Any = y match {
580	        case t: VarType => walkVarType(t)
581	        case t: TraitType => walkTraitType(t)
582	        case t: TupleType => walkTupleType(t)
583	        case t: ArrowType => walkArrowType(t)
584	        case _ => walkOtherType(y)
585	      }
586	      def walkVarType(t: VarType) = {
587	        t match { case SVarType(_, n, _) =>
588	            if (cacheNormalizeVar)
589	              normalizeVarTypeMemo.get(n) match {
590	                case Some(v) => noteNorm(n); v
591	                case _ =>
592	                  val before = traits.contextReads
593	                  val result = walkVarTypeInner(t, n)
594	                  normalizeVarTypeMemo += (n -> result)
595	                  markNorm(before, n)
596	                  result
597	              }
598	            else walkVarTypeInner(t, n)
599	        }
600	      }
601	      def walkVarTypeInner(t: VarType, n: Id) = super.walk(t)
602	      def walkTraitType(t: TraitType) = {
603	        t match { case STraitType(_, n, a, _) =>
604	            if (cacheNormalizeTrait) {
605	              normalizeTraitTypeMemo.get((n, a)) match {
606	                case Some(v) => noteNorm((n, a)); v
607	                case _ =>
608	                  val before = traits.contextReads
609	                  walkTraitTypeInner(t, n, a) match {
610	                    case result@STraitType(_, _, aa, _) =>
611	                       normalizeTraitTypeMemo += ((n, a) -> result)
612	                       normalizeTraitTypeMemo += ((n, aa) -> result)
613	                       markNorm(before, (n, a), (n, aa))
614	                       result
615	                  }
616	              }
617	            }
618	            else walkTraitTypeInner(t, n, a)
619	        }
620	      }
621	      def walkTraitTypeInner(t: TraitType, n: Id, a: List[StaticArg]) = {
622	        typeCons(n) match {
623	          case ti: TypeAliasIndex =>
624	            val params = toListFromImmutable(ti.staticParameters)
625	            walk(substitute(a, params, ti.ast.getTypeDef))
626	          case _ => super.walk(t)
627	        }
628	      }
629	      def walkTupleType(t: TupleType) = {
630	        if (cacheNormalizeTuple)
631	          t match { case STupleType(_, e, vt, _) =>
632	              normalizeTupleTypeMemo.get((e, vt)) match {
633	                case Some(v) => noteNorm((e, vt)); v
634	                case _ =>
635	                  val before = traits.contextReads
636	                  walkTupleTypeInner(t) match {
637	                    case result@STupleType(_, ee, vtx, _) =>
638	                      normalizeTupleTypeMemo += ((e, vt) -> result)
639	                      normalizeTupleTypeMemo += ((ee, vtx) -> result)
640	                      markNorm(before, (e, vt), (ee, vtx))
641	                      result
642	                    case result =>
643	                      normalizeTupleTypeMemo += ((e, vt) -> result)
644	                      markNorm(before, (e, vt))
645	                      result
646	                  }
647	              }
648	          }
649	        else walkTupleTypeInner(t)
650	      }
651	      def walkTupleTypeInner(t: TupleType) = {
652	        //ToDo: Handle keywords
653	        super.walk(t) match {
654	          case STupleType(i, e, Some(v: BottomType), k) => STupleType(i, e, None, k)
655	          case STupleType(i, e, vt, k) if e.contains(bottom) => bottom
656	          case STupleType(i, e, None, Nil) if (e.size == 1) => e.head
657	          case _ => t
658	        }
659	      }
660	      def walkArrowType(t: ArrowType) = {
661	        if (cacheNormalizeArrow)
662	          t match { case SArrowType(_, d, r, e, i, _) =>
663	              normalizeArrowTypeMemo.get((d, r, e, i)) match {
664	                case Some(v) => noteNorm((d, r, e, i)); v
665	                case _ =>
666	                  val before = traits.contextReads
667	                  walkArrowTypeInner(t) match {
668	                    case result@SArrowType(_, dd, rr, ee, ii, _) =>
669	                      normalizeArrowTypeMemo += ((d, r, e, i) -> result)
670	                      normalizeArrowTypeMemo += ((dd, rr, ee, ii) -> result)
671	                      markNorm(before, (d, r, e, i), (dd, rr, ee, ii))
672	                      result
673	                  }
674	              }
675	          }
676	        else walkArrowTypeInner(t)
677	      }
678	      def walkArrowTypeInner(t: ArrowType) = super.walk(t)
679	      def walkOtherType(t: Any) = {
680	        if (cacheNormalizeOther)
681	          normalizeOtherTypeMemo.get(t) match {
682	            case Some(v) => noteNorm(t); v
683	            case _ =>
684	              val before = traits.contextReads
685	              val result = walkOtherTypeInner(t)
686	              normalizeOtherTypeMemo += (t -> result)
687	              markNorm(before, t)
688	              result
689	          }
690	        else walkOtherTypeInner(t)
691	      }
692	      def walkOtherTypeInner(t: Any) = t match {
693	        case u@SUnionType(_, e) =>
694	          val ps = e.flatMap(t => disjuncts(walk(t).asInstanceOf[Type]))
695	          makeUnionType(normDisjunct(ps))
696	        case i@SIntersectionType(_, e) =>
697	          val sop = cross(e.map(t => disjuncts(walk(t).asInstanceOf[Type])))
698	          val ps = sop.map(t => makeIntersectionType(normConjunct(t.flatMap(disjuncts))))
699	          makeUnionType(normDisjunct(ps))
700	        case o:Op => normalize(o)
701	        case _ => super.walk(t)
702	      }
703	    }
704	    // Here's the body: walk the type, and make sure it's a type when finished
705	    normalizer(x).asInstanceOf[Type]
706	  }
