742	  //ToDo: Keywords
743	  protected def normTuples(x: TupleType, y: TupleType)(implicit history: Set[hType]): TupleType = (x,y) match {
744	    case (STupleType(_, e1, None, _), STupleType(_, e2, None, _)) =>
745	      STupleType(makeInfo(e1), (e1, e2).zipped.map((a,b) => pMeet(a,b)), None, Nil)
746	    case (STupleType(_, e1, None, _), STupleType(_, e2, Some(_), _)) =>
747	      normTuples(x, disjunctFromTuple(y, e1.size).asInstanceOf[TupleType])
748	    case (STupleType(_, e1, Some(_), _), STupleType(_, e2, None, _)) =>
749	      normTuples(disjunctFromTuple(x, e2.size).asInstanceOf[TupleType], y)
750	    case (STupleType(_, e1, Some(v1), _), STupleType(_, e2, Some(v2), _)) => {
751	      val ee1 = e1 ++ List.fill(e2.size - e1.size){v1}
752	      val ee2 = e2 ++ List.fill(e1.size - e2.size){v2}
753	      STupleType(makeInfo(e1), (ee1, ee2).zipped.map((a,b) => pMeet(a,b)), Some(pMeet(v1, v2)), Nil)
754	    }
755	  }
