794	  def comprisesClause(t: TraitType): Set[TraitType] = typeCons(t.getName) match {
795	    case ti: ProperTraitIndex =>
796	      val args = toListFromImmutable(t.getArgs)
797	      val params = toListFromImmutable(ti.staticParameters)
798	      toSet(ti.comprisesTypes).map(nt => if (!nt.isInstanceOf[TraitType]) return Set()
799	                                         else openWhereSizes(ti, substitute(args, params, nt)).asInstanceOf[TraitType])
