866	  /* The analyzer in which a type an excludes clause names is read: a trait that excludes
867	   * another is added to the other's clause at its own static parameters
868	   * (IndexBuilder.checkTraitClauses), which are not in scope where that clause is read,
869	   * so the ones not in scope are added. */
870	  private def withClauseParams(e: TraitType): TypeAnalyzer = {
871	    val free = toListFromImmutable(e.getArgs).collect {
872	      case STypeArg(_, _, SVarType(_, n, _)) if { traits.readContext(); !env.contains(n) } => n.getText }
873	    if (free.isEmpty) this
874	    else typeCons(e.getName) match {
875	      case ti: TraitIndex =>
876	        val params = toListFromImmutable(ti.staticParameters).filter(p => free.contains(p.getName.getText))
877	        if (params.isEmpty) this else extend(params, None)
878	      case _ => this
879	    }
880	  }
