910	  def pTrue()(implicit negate: Boolean) = 
911	    if (negate) False else True
912	  def pFalse()(implicit negate: Boolean) = 
913	    if (negate) True else False
914	  def pAnd(c1: CFormula, c2: CFormula)(implicit ta: TypeAnalyzer, negate: Boolean) = 
915	    if (negate) or(c1, c2) else and(c1, c2)
916	  def pAnd(cs: Iterable[CFormula])(implicit ta: TypeAnalyzer, negate: Boolean): CFormula = 
917	    if (negate) or(cs) else and(cs)
918	  def pOr(c1: CFormula, c2: CFormula)(implicit ta: TypeAnalyzer, negate: Boolean) = 
919	    if (negate) and(c1, c2) else or(c1, c2)
920	  def pOr(cs: Iterable[CFormula])(implicit ta: TypeAnalyzer, negate: Boolean) = 
921	    if (negate) and(cs) else or(cs)
922	  def pUpperBound(i: _InferenceVarType, t: Type)(implicit negate: Boolean) = 
923	    if (negate) notUpperBound(i, t) else upperBound(i, t)
924	  def pLowerBound(i: _InferenceVarType, t: Type)(implicit negate: Boolean) = 
925	    if (negate) notLowerBound(i, t) else lowerBound(i, t)
